    const reader = await PdfReader.create(await importSqliteDatabase(bytes), PDF17_SQLITE_SCHEMA, {}, pdfFontNumberColumns); expect(await readPdfCidFont(reader, encoded.root)).toEqual(value); await reader.finish();
    sql.close();
  }
